String hp(String s)=>sha256.convert(utf8.encode(s)).toString();

class User{String username,name,role,password;User({required this.username,required this.name,required this.role,required this.password});Map<String,dynamic> j()=>{'username':username,'name':name,'role':role,'password':password};factory User.from(Map<String,dynamic>x)=>User(username:'${x['username']??''}',name:'${x['name']??''}',role:'${x['role']??'مشاور'}',password:'${x['password']??''}');}
