bool get manager=>me?.role=='مدیر'||me?.role=='مدیر فروش';

class DB{static const u='users5',p='props5',c='clients5',m='meetings5',d='dark5';static Future<SharedPreferences> get s=>SharedPreferences.getInstance();static Future<List<User>> users()async{final x=await s;final raw=x.getString(u);if(raw==null){final a=[User(username:'admin',name:'مهندس مجتبی صفری',role:'مدیر',password:hp('1234')),User(username:'sales',name:'خانم طهماسبی پور',role:'مدیر فروش',password:hp('1234')),User(username:'moshaver1',name:'مشاور اول',role:'مشاور',password:hp('1234'))];await saveUsers(a);return a;}return(jsonDecode(raw)as List).map((e)=>User.from(Map<String,dynamic>.from(e))).toList();}static Future<void> saveUsers(List<User>x)async=>(await s).setString(u,jsonEncode(x.map((e)=>e.j()).toList()));static Future<void> load()async{final x=await s;try{props..clear()..addAll((jsonDecode(x.getString(p)??'[]')as List).map((e)=>Property.from(Map<String,dynamic>.from(e))));}catch(_){props.clear();}clients..clear()..addAll(x.getStringList(c)??[]);meetings..clear()..addAll(x.getStringList(m)??[]);}static Future<void> saveProps()async=>(await s).setString(p,jsonEncode(props.map((e)=>e.j()).toList()));static Future<void> saveClients()async=>(await s).setStringList(c,clients);static Future<void> saveMeetings()async=>(await s).setStringList(m,meetings);static Future<bool> dark()async=>(await s).getBool(d)??false;static Future<void> setDark(bool v)async=>(await s).setBool(d,v);}

